#include <bits/stdc++.h>
using namespace std;

const long long MOD = 998244353;

long long powMod(long long base, long long exp) {
    long long res = 1;
    while (exp > 0) {
        if (exp & 1) res = (res * base) % MOD;
        base = (base * base) % MOD;
        exp >>= 1;
    }
    return res;
}

vector<long long> factorials;

long long combination(int n, int r) {
    if (n < r) return 0;
    long long numerator = factorials[n];
    long long denominator = (factorials[n - r] * factorials[r]) % MOD;
    return (numerator * powMod(denominator, MOD - 2)) % MOD;
}

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);
    int maxN = 200001;
    factorials.resize(maxN);
    factorials[0] = 1;
    for (int i = 1; i < maxN; i++) {
        factorials[i] = (factorials[i - 1] * i) % MOD;
    }
    int n;
    long long k;
    cin >> n >> k;
    if (k >= n) {
        cout << 0 << "\n";
        return 0;
    }
    if (k == 0) {
        cout << factorials[n] << "\n";
        return 0;
    }
    if (k == n - 1) {
        cout << 2LL * n << "\n";
        return 0;
    }
    int filledCols = n - (int)k;
    long long chooseFilledCols = combination(n, filledCols);
    long long totalWays = 0;
    for (int emptyCols = 0; emptyCols <= filledCols; emptyCols++) {
        long long choose = combination(filledCols, emptyCols);
        long long fillWays = powMod(filledCols - emptyCols, n);
        long long val = (choose * fillWays) % MOD;
        if (emptyCols % 2 == 1) val = (MOD - val) % MOD;
        totalWays = (totalWays + val) % MOD;
    }
    totalWays = (totalWays * chooseFilledCols) % MOD;
    totalWays = (totalWays * 2) % MOD;
    cout << totalWays << "\n";
    return 0;
}
